/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `complaint_AFTER_INSERT` AFTER INSERT ON `complaint` FOR EACH ROW BEGIN
	update surveyor set avail = avail + 1 where s_id = new.s_id_fk;
END */;;
